import {cn} from '@ui/utils/cn';
import {ComponentProps} from 'react';

function TableRoot({className, ...props}: ComponentProps<'table'>) {
  return (
    <div data-slot="table-container" className="relative w-full">
      <table
        data-slot="table"
        className={cn('w-full text-sm', className)}
        {...props}
      />
    </div>
  );
}

function TableHeader({className, ...props}: ComponentProps<'thead'>) {
  return (
    <thead
      data-slot="table-header"
      className={cn('[&_tr]:border-b', className)}
      {...props}
    />
  );
}

function TableBody({className, ...props}: ComponentProps<'tbody'>) {
  return (
    <tbody
      data-slot="table-body"
      className={cn('[&_tr:last-child]:border-0', className)}
      {...props}
    />
  );
}

function TableFooter({className, ...props}: ComponentProps<'tfoot'>) {
  return (
    <tfoot
      data-slot="table-footer"
      className={cn(
        'border-t bg-muted/50 font-medium [&>tr]:last:border-b-0',
        className,
      )}
      {...props}
    />
  );
}

function TableRow({
  className,
  selected,
  ...props
}: ComponentProps<'tr'> & {selected?: boolean}) {
  return (
    <tr
      data-slot="table-row"
      className={cn(
        'border-b transition-colors hover:bg-muted/50 has-aria-expanded:bg-muted/50',
        selected && 'bg-muted',
        className,
      )}
      {...props}
    />
  );
}

function TableHead({className, ...props}: ComponentProps<'th'>) {
  return (
    <th
      data-slot="table-head"
      className={cn(
        'h-12 w-(--width) content-center px-3 text-start align-middle font-medium whitespace-nowrap text-foreground has-[[role=checkbox]]:w-[1%] has-[[role=checkbox]]:pe-1.5',
        className,
      )}
      {...props}
    />
  );
}

function TableCell({className, ...props}: ComponentProps<'td'>) {
  return (
    <td
      data-slot="table-cell"
      className={cn(
        'p-3 align-middle whitespace-nowrap has-[[role=checkbox]]:pe-1.5',
        className,
      )}
      {...props}
    />
  );
}

function TableCaption({className, ...props}: ComponentProps<'caption'>) {
  return (
    <caption
      data-slot="table-caption"
      className={cn('mt-4 text-sm text-muted-foreground', className)}
      {...props}
    />
  );
}

const Table = Object.assign(TableRoot, {
  Root: TableRoot,
  Header: TableHeader,
  Body: TableBody,
  Footer: TableFooter,
  Row: TableRow,
  Head: TableHead,
  Cell: TableCell,
  Caption: TableCaption,
});

export {Table};
